const $=s=>document.querySelector(s);
const foods=[['stick','🥖','과자 스틱','classic'],['postick','🍟','포스틱','classic'],['cabbage','🥬','배추','wild'],['enoki','🍄','팽이버섯','wild'],['cilantro','🌿','고수','wild'],['sujebi','🥟','수제비','wild'],['ramen','🍜','라면','wild'],['cucumber','🥒','오이','wild'],['shrimp','🍤','새우튀김','wild'],['ricecake','🍡','떡','classic'],['pretzel','🥨','프레첼','classic'],['bacon','🥓','베이컨','wild'],["strawberry","","딸기","classic"],["banana","","바나나","classic"],["apple","","사과","classic"],["grape","","포도","classic"],["pineapple","","파인애플","classic"],["orange","","오렌지","classic"],["broccoli","","브로콜리","wild"],["carrot","","당근","wild"],["corn","","옥수수","wild"],["potato","","감자","wild"],["sweetpotato","","군고구마","classic"],["kingoyster","","새송이버섯","wild"],["sausage","","소시지","wild"],["cheese","","치즈","classic"],["kimchi","","김치","wild"],["gimbap","","김밥","wild"],["dumpling","","만두","wild"],["fishcake","","어묵","wild"]].map(([id,emoji,name,category])=>({id,emoji,name,category}));
const chocolates=[{id:'milk',name:'밀크 초콜릿',note:'달콤하고 부드럽게',color:'#74452e'},{id:'dark',name:'다크 초콜릿',note:'진하고 쌉싸름하게',color:'#3e2926'},{id:'white',name:'화이트 초콜릿',note:'포근하고 달콤하게',color:'#f0dfb1'},{id:'strawberry',name:'딸기 초콜릿',note:'분홍빛으로 사랑스럽게',color:'#df8e96'},{id:'matcha',name:'말차 초콜릿',note:'향긋하고 초록하게',color:'#8a9c60'},{id:'mint',name:'민트 초콜릿',note:'시원한 민초파의 선택',color:'#8dbbae'}];
const toppings=[['rainbow','🌈','레인보우'],['almond','🥜','아몬드'],['hearts','💗','하트 캔디'],['sesame','⚪','참깨'],['chili','🌶️','고춧가루'],['seaweed','🌿','김가루']].map(([id,emoji,name])=>({id,emoji,name}));
const state={step:0,selected:['stick'],choc:'milk',melt:0,coat:0,topping:'rainbow',dots:[],to:'',from:'',message:'조금 이상해도, 내 마음은 진심이야!',paper:'#f5dfd7',filter:'all'};
let timer=null,busy=false,toastTimer; const canvas=$('#creation'),ctx=canvas.getContext('2d');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function selectedFoods(){return state.selected.map(id=>foods.find(f=>f.id===id)).filter(Boolean)}
function chocolate(){return chocolates.find(c=>c.id===state.choc)}
function round(c,x,y,w,h,r,fill){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill()}}
function ellipse(c,x,y,rx,ry,color){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=color;c.fill()}
function line(c,points,color,width){c.beginPath();c.moveTo(...points[0]);points.slice(1).forEach(p=>c.lineTo(...p));c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.lineJoin='round';c.stroke()}
function rng(seed){let a=seed;return()=>{a=(a*1664525+1013904223)>>>0;return a/4294967296}}
function legacyFoodImage(food,coating=0,decorations=[]){
 const o=document.createElement('canvas');o.width=220;o.height=440;const c=o.getContext('2d');const r=rng(42);
 if(['stick','postick','cucumber','ricecake','bacon','custom'].includes(food.id)||food.id.startsWith('custom')){
  const colors={stick:'#d8a35d',postick:'#e7ba62',cucumber:'#7e9b47',ricecake:'#f0e5d1',bacon:'#cd8071'};round(c,85,30,50,365,22,colors[food.id]||'#d7b887');
  for(let i=0;i<12;i++){const y=48+i*28;if(food.id==='bacon')line(c,[[93,y],[126,y+15]],'#f6d9b9',9);else if(food.id==='cucumber'){line(c,[[93,y],[93,y+13]],'#a9b965',3);line(c,[[127,y],[127,y+13]],'#4e713b',3)}else if(food.id==='postick')line(c,[[94,40],[94,382]],'#f4d78c',3);else ellipse(c,96+r()*27,y,1.8,2.5,'#a9743f66')}
  if(food.id==='ricecake'){for(let i=0;i<4;i++)line(c,[[90,95+i*72],[130,95+i*72]],'#ddd0b7',2)}
 }else if(food.id==='cabbage'){
  for(let i=0;i<7;i++){c.save();c.translate(110,330);c.rotate((i-3)*.115);ellipse(c,0,-165,40,140,['#78945a','#a3b773','#bdd08b'][i%3]);line(c,[[0,25],[0,-255]],'#e1e5b8',8);for(let j=0;j<6;j++){let y=-50-j*31;line(c,[[0,y+25],[-27,y]],'#d0dba5',2);line(c,[[0,y+25],[27,y]],'#d0dba5',2)}c.restore()}round(c,91,301,38,96,10,'#e5e6c1');
 }else if(food.id==='enoki'){
  for(let i=0;i<13;i++){let x=38+i*12,y=40+Math.sin(i*3)*30;line(c,[[110+(i-6)*3,390],[x+12,y+20]],'#dfd8bd',8);line(c,[[109+(i-6)*3,389],[x+10,y+20]],'#fff7df',4);ellipse(c,x+12,y+14,14,10,'#eee0bc');ellipse(c,x+10,y+11,12,8,'#fff5d9')}
 }else if(food.id==='cilantro'){
  for(let i=0;i<9;i++){let x=36+i*18,y=45+(i%3)*65;line(c,[[110,396],[x,y]],'#60804a',6);for(let j=0;j<4;j++){let yy=y+j*20;ellipse(c,x-11,yy,16,11,j%2?'#819d56':'#617e48');ellipse(c,x+9,yy-7,15,12,'#72924d')}}
 }else if(food.id==='ramen'){
  round(c,50,45,120,270,13,'#e8c16d');for(let j=0;j<14;j++){c.beginPath();for(let i=0;i<=40;i++){let x=56+i*2.8,y=53+j*18+Math.sin(i*.8+j)*6;i?c.lineTo(x,y):c.moveTo(x,y)}c.strokeStyle=j%2?'#f7d98a':'#ca9c4e';c.lineWidth=7;c.stroke()}line(c,[[110,300],[110,395]],'#d7a75a',14)
 }else if(food.id==='sujebi'){
  line(c,[[110,80],[110,398]],'#c49958',9);for(let i=0;i<5;i++){c.save();c.translate(110,75+i*57);c.rotate(i%2?.3:-.3);ellipse(c,0,0,45,35,'#d3c6ab');ellipse(c,-2,-4,43,32,'#f0e4cc');c.restore()}
 }else if(food.id==='shrimp'){
  line(c,[[110,390],[100,90]],'#d7a050',58);for(let i=0;i<100;i++)ellipse(c,80+r()*50,74+r()*290,3+r()*5,3+r()*4,r()>.5?'#efc26c':'#c68c37');c.beginPath();c.moveTo(91,65);c.lineTo(70,25);c.lineTo(109,46);c.lineTo(137,20);c.lineTo(123,75);c.fillStyle='#d6754e';c.fill();
 }else if(food.id==='pretzel'){
  line(c,[[110,270],[110,398]],'#c8914d',15);c.beginPath();c.moveTo(110,230);c.bezierCurveTo(-20,90,60,-20,110,125);c.bezierCurveTo(160,-20,240,90,110,230);c.bezierCurveTo(20,270,30,160,160,160);c.strokeStyle='#c18b49';c.lineWidth=25;c.lineCap='round';c.stroke();
 }
 if(coating>0){c.globalCompositeOperation='source-atop';let end=30+coating*275;c.fillStyle=chocolate().color;c.fillRect(0,0,220,end);for(let i=0;i<7;i++){ellipse(c,40+i*24,end,12,8+Math.sin(i)*6,chocolate().color)}c.fillStyle='#ffffff16';c.fillRect(80,0,9,end-10);
  decorations.forEach(d=>{const rr=rng(d.seed);for(let i=0;i<12;i++){const x=d.x+(rr()-.5)*90,y=d.y+(rr()-.5)*75;if(y>end-4)continue;const col={almond:'#e4c48e',hearts:'#f6b7bc',sesame:'#f5ebce',chili:'#a83c22',seaweed:'#344e32'}[d.type];c.save();c.translate(x,y);c.rotate(rr()*6.3);if(d.type==='hearts'){c.fillStyle=col;c.beginPath();c.moveTo(0,4);c.bezierCurveTo(-13,-4,-8,-12,0,-6);c.bezierCurveTo(8,-12,13,-4,0,4);c.fill()}else if(d.type==='rainbow')round(c,-2,-6,4,12,2,['#f5c95b','#f5e4c7','#db7a86','#91ad87'][i%4]);else ellipse(c,0,0,d.type==='almond'?4:2,d.type==='almond'?8:4,col);c.restore()}});c.globalCompositeOperation='source-over';
 }
 if(food.id.startsWith('custom')){round(c,55,333,110,34,6,'#fff5de');c.fillStyle='#694e37';c.font='bold 15px sans-serif';c.textAlign='center';c.fillText(food.name,110,356,100)}return o;
}

const foodAtlas=new Image(),extraFoodAtlas=new Image();
function loadFoodAtlas(image,src){return new Promise(resolve=>{image.onload=()=>resolve(true);image.onerror=()=>resolve(false);image.src=src})}
const foodAtlasReady=Promise.all([loadFoodAtlas(foodAtlas,'assets/food-icons-v2.png'),loadFoodAtlas(extraFoodAtlas,'assets/food-icons-extra-v2.png')]);
function foodPhoto(food){const i=foods.findIndex(f=>f.id===food.id);if(i<0||i>=30)return null;const extra=i>=12;return {image:extra?extraFoodAtlas:foodAtlas,index:extra?i-12:i,cols:extra?6:4,rows:3,extra}}
function materialIcon(item,topping=false){if(item.id.startsWith('custom'))return '<span class="custom-food-icon" aria-hidden="true">＋</span>';const photo=topping?null:foodPhoto(item),i=topping?toppings.findIndex(t=>t.id===item.id):photo.index,cols=topping?3:photo.cols,rows=topping?2:photo.rows;return '<span class="material-icon '+(topping?'topping-photo':photo.extra?'extra-food-photo':'food-photo')+'" aria-hidden="true" style="--icon-x:'+(i%cols)*100/(cols-1)+'%;--icon-y:'+Math.floor(i/cols)*100/(rows-1)+'%"></span>'}
function foodImage(food,coating=0,decorations=[]){return renderCoatedFood(food,coating,decorations)}
function foodLayout(w,h,n,i){const size=Math.min(w,h)*(n===1?.68:n===2?.54:.47);return {x:w*(n===1?.5:n===2?[.34,.66][i]:[.29,.71,.50][i]),y:h*(n===3?[.43,.43,.69][i]:.53),size,rotation:n===1?-.05:n===2?[-.13,.13][i]:[-.12,.12,-.04][i]}}

function plate(c,w,h){c.save();ellipse(c,w*.5,h*.58,w*.39,h*.31,'#b9a58b18');ellipse(c,w*.5,h*.54,w*.39,h*.31,'#fffaf0');c.strokeStyle='#e1d7c5';c.lineWidth=2;c.beginPath();c.ellipse(w*.5,h*.54,w*.355,h*.278,0,0,Math.PI*2);c.stroke();c.restore()}
function arrangement(c,w,h,coating=state.coat,decorations=state.dots){const fs=selectedFoods();plate(c,w,h);const list=fs.length?fs:[foods[0]];list.forEach((f,i)=>{const p=foodLayout(w,h,list.length,i);c.save();c.translate(p.x,p.y);c.rotate(p.rotation);c.shadowColor='#68432b2b';c.shadowBlur=8;c.shadowOffsetY=9;c.drawImage(foodImage(f,coating,decorations.filter(d=>d.food===i)),-p.size/2,-p.size/2,p.size,p.size);c.restore()})}
function bowl(c,p,dipping=false){c.save();c.translate(440,475);ellipse(c,8,112,245,45,'#7c5e3620');c.beginPath();c.moveTo(-220,0);c.bezierCurveTo(-190,190,190,190,220,0);c.fillStyle='#b6a893';c.fill();c.beginPath();c.moveTo(-204,0);c.bezierCurveTo(-175,165,175,165,204,0);c.fillStyle='#d7cbbb';c.fill();ellipse(c,0,0,224,82,'#e5dac8');ellipse(c,0,-3,201,63,chocolate().color);if(!dipping){for(let i=0;i<7;i++){c.save();c.translate((i%3-1)*90,(Math.floor(i/3)-1)*25);c.rotate((i-3)*.3);c.globalAlpha=1-p/100;round(c,-35,-22,65*(1-p/150),45*(1-p/150),5,chocolate().color);c.strokeStyle='#ffffff22';c.stroke();c.restore()}c.save();c.rotate(-.4+p*.04);line(c,[[30,0],[140,-250]],'#b59060',23);ellipse(c,30,0,27,14,'#d8b27b');c.restore()}else{const f=selectedFoods()[0];c.save();c.translate(0,-255+Math.sin(p/100*Math.PI)*150);c.rotate(.13);c.drawImage(foodImage(f,p/100),-135,-135,270,270);c.restore();ellipse(c,0,22,190,40,chocolate().color)}for(let i=0;i<3;i++){c.beginPath();c.moveTo(-90+i*90,-115);c.bezierCurveTo(-120+i*90,-160,-60+i*90,-175,-85+i*90,-210);c.strokeStyle='#b5a28b66';c.lineWidth=4;c.stroke()}c.restore()}
function draw(){ctx.clearRect(0,0,880,880);if(state.step===1)bowl(ctx,state.melt);else if(state.step===2&&state.coat<1)bowl(ctx,state.coat*100,true);else if(state.step===4){drawGift(ctx,880,880)}else arrangement(ctx,880,880,state.step===0?0:state.coat);}
function drawHero(){const c=$('#hero').getContext('2d');c.clearRect(0,0,1000,660);c.save();c.translate(500,330);c.rotate(-.12);round(c,-300,-210,600,420,130,'#eedbca');round(c,-276,-190,552,380,115,'#f8ead7');c.strokeStyle='#d4bca1';c.lineWidth=2;c.stroke();c.restore();const old=state.choc;[{food:foods[2],x:340,y:302,r:-.35,choc:'strawberry'},{food:foods[0],x:555,y:325,r:.18,choc:'milk'},{food:foods[3],x:680,y:305,r:.42,choc:'white'}].forEach((f,i)=>{state.choc=f.choc;c.save();c.translate(f.x,f.y);c.rotate(f.r);c.shadowColor='#68432b33';c.shadowBlur=12;c.shadowOffsetY=12;c.drawImage(foodImage(f.food,1,[{x:100,y:150,type:i===1?'almond':'rainbow',seed:22}]),-150,-150,300,300);c.restore()});state.choc=old;c.fillStyle='#c74f42';c.font='28px serif';c.fillText('✦',120,440);c.fillText('✧',815,175);c.font='25px serif';c.fillText('♡',740,530)}
function wrapText(c,text,x,y,max,lineHeight,maxLines=3){let lineText='',lines=0;for(const letter of text){if(c.measureText(lineText+letter).width>max){c.fillText(lineText,x,y);lineText='';y+=lineHeight;lines++;if(lines>=maxLines)return}lineText+=letter}c.fillText(lineText,x,y)}
function drawGift(c,w,h){c.save();c.scale(w/1000,h/1000);round(c,35,20,930,960,28,state.paper);c.strokeStyle='#fff7ed';c.lineWidth=2;round(c,60,45,880,910,20);c.stroke();c.textAlign='center';c.fillStyle='#8b6655';c.font='14px sans-serif';c.fillText('A LITTLE STRANGE, A LOT OF LOVE',500,96);c.fillStyle='#583a31';c.font='bold 40px sans-serif';c.fillText('너를 위한 아무거나 빼빼로',500,163);c.font='20px sans-serif';c.fillText(state.to?`To. ${state.to}`:'HAPPY PEPERO DAY',500,210);c.save();c.translate(100,200);arrangement(c,800,580,1);c.restore();c.fillStyle='#694b3e';c.font='bold 21px sans-serif';c.fillText(selectedFoods().map(f=>f.name).join(' + ')+` × ${chocolate().name}`,500,795,790);c.font='23px sans-serif';wrapText(c,state.message||'조금 이상해도, 내 마음은 진심이야!',500,844,780,31,2);c.font='17px sans-serif';c.fillText(state.from?`From. ${state.from}`:'WITH LOVE, 11.11',500,929);c.restore()}
const stepTitles=['재료 고르기','초콜릿 중탕','초콜릿 입히기','마음껏 꾸미기','선물하기'];
function render(){
 const ingredientScroll=$('.filter.active')?.dataset.filter===state.filter?($('.ingredients')?.scrollTop||0):0;
 $('.steps').innerHTML=stepTitles.map((s,i)=>`<div class="step ${i===state.step?'active':i<state.step?'done':''}" ${i===state.step?'aria-current="step"':''}><b>${i<state.step?'✓':'0'+(i+1)}</b>${s}</div>`).join('');
 $('#step-label').textContent=`STEP 0${state.step+1}`;
 $('#step-title').textContent=['무엇으로 만들어 볼까요?','초콜릿을 사르르 녹여요.','초콜릿에 퐁당!','조금 더 엉뚱해도 좋아요.','이 마음, 포장해 드릴게요.'][state.step];
 $('#step-description').textContent=['빼빼로의 가능성은 무한해요. 최대 3개를 골라 주세요.','어떤 초콜릿이든 좋아요. 중탕으로 부드럽게 녹여요.','고른 재료에 녹인 초콜릿을 듬뿍 입혀 주세요.','토핑을 고르고 오른쪽 빼빼로를 눌러 뿌려 주세요.','받는 사람과 한마디를 적어 이미지로 선물하세요.'][state.step];
 $('#preview-tag').textContent=['재료 탐색 중','초콜릿 중탕 중','달콤하게 코팅 중','내 취향으로 꾸미는 중','마음까지 포장 완료'][state.step];
 $('#recipe-text').textContent=selectedFoods().map(f=>f.name).join(' + ')||'재료를 골라 주세요';
 $('#recipe-caption').textContent=state.step>0?`+ ${chocolate().name}${state.coat===1?' · 초콜릿 코팅 완료':''}`:`${state.selected.length} / 3개 선택 · 엉뚱할수록 좋아요`;
 $('#canvas-hint').textContent=state.step===3?'톡톡 눌러 토핑을 뿌려요 ✦':'';
 $('#back').hidden=state.step===0;$('#back').disabled=busy;$('#next').hidden=state.step===4;
 $('#next').innerHTML=['초콜릿 고르기 <span>→</span>','초콜릿 입히기 <span>→</span>','토핑으로 꾸미기 <span>→</span>','선물 포장하기 <span>→</span>',''][state.step];
 $('#next').disabled=busy||!state.selected.length||(state.step===1&&state.melt<100)||(state.step===2&&state.coat<1);
 const box=$('#choices');
 if(state.step===0){box.innerHTML=`<div class="filters">${[['all','모두'],['classic','익숙한 맛'],['wild','도전하는 맛']].map(([id,n])=>`<button class="filter ${state.filter===id?'active':''}" data-filter="${id}">${n}</button>`).join('')}</div><div class="ingredients" role="group" aria-label="재료 30종">${foods.filter(f=>state.filter==='all'||f.category===state.filter).map(f=>`<button class="ingredient ${state.selected.includes(f.id)?'selected':''}" aria-pressed="${state.selected.includes(f.id)}" data-food="${f.id}">${materialIcon(f)}${esc(f.name)}</button>`).join('')}</div><form class="custom" id="custom-form"><input id="custom-name" aria-label="나만의 재료 이름" placeholder="이것도 되나요? 직접 입력하기" maxlength="12"><button>+ 추가</button></form><p class="smallprint">✳ 기본 재료 30종 + 직접 추가 · 한 작품에 최대 3개</p>`;
 box.querySelectorAll('[data-food]').forEach(b=>b.onclick=()=>{const id=b.dataset.food;if(state.selected.includes(id))state.selected=state.selected.filter(x=>x!==id);else if(state.selected.length<3)state.selected.push(id);else return toast('한 작품에는 최대 3개까지 담을 수 있어요.');state.dots=[];state.coat=0;render()});
 box.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});$('#custom-form').onsubmit=e=>{e.preventDefault();let name=$('#custom-name').value.trim();if(!name)return toast('재료 이름을 적어 주세요.');if(state.selected.length>=3)return toast('선택한 재료 하나를 빼고 추가해 주세요.');let f=foods.find(f=>f.name===name);if(!f){f={id:'custom'+Date.now(),name,emoji:'✨',category:'wild'};foods.push(f)}if(!state.selected.includes(f.id))state.selected.push(f.id);state.filter='all';state.coat=0;state.dots=[];render()};
 }else if(state.step===1){box.innerHTML=`<div class="chocolates">${chocolates.map(c=>`<button class="chocolate ${c.id===state.choc?'selected':''}" aria-pressed="${c.id===state.choc}" data-choc="${c.id}" ${busy?'disabled':''}><span class="swatch" style="background:${c.color}"></span><span>${c.name}<small>${c.note}</small></span></button>`).join('')}</div><div class="experiment"><p id="melt-text">${state.melt===100?'✓ 매끈하게 녹았어요. 이제 재료를 담가 볼까요?':'따뜻한 물 위에서 초콜릿을 저어 주세요.'}</p><div class="progress-track" role="progressbar" aria-label="초콜릿 중탕" aria-valuenow="${state.melt}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${state.melt}%"></div></div><button id="melt" ${state.melt===100||busy?'disabled':''}>${state.melt===100?'중탕 완료 ✓':busy?'사르르 녹이는 중…':'🥄 저으며 중탕하기'}</button></div>`;
 box.querySelectorAll('[data-choc]').forEach(b=>b.onclick=()=>{state.choc=b.dataset.choc;state.melt=0;state.coat=0;state.dots=[];state.coat=0;render()});$('#melt').onclick=()=>animate('melt',100,4000);
 }else if(state.step===2){box.innerHTML=`<div class="experiment"><div style="font-size:46px">🍫</div><p>준비한 ${esc(selectedFoods().map(f=>f.name).join(', '))}에<br>${chocolate().name}을 입혀 볼까요?</p><div class="progress-track" role="progressbar" aria-label="초콜릿 코팅" aria-valuenow="${Math.round(state.coat*100)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${state.coat*100}%"></div></div><button id="dip" ${state.coat===1||busy?'disabled':''}>${state.coat===1?'코팅 완료 ✓':busy?'퐁당, 초콜릿 입히는 중…':'퐁당! 초콜릿에 담그기'}</button><p>${state.coat===1?'모든 재료에 달콤한 초콜릿이 입혀졌어요.':'재료의 일부는 그대로 남겨 원래 모양을 살릴게요.'}</p></div>`;$('#dip').onclick=()=>animate('coat',1,2700);
 }else if(state.step===3){box.innerHTML=`<div class="toppings">${toppings.map(t=>`<button class="topping ${state.topping===t.id?'selected':''}" aria-pressed="${state.topping===t.id}" data-topping="${t.id}">${materialIcon(t,true)}${t.name}</button>`).join('')}</div><div class="experiment"><p>토핑을 골랐다면 빼빼로를 톡톡!<br>휴대폰에서는 위쪽 미리보기를 눌러 주세요.</p><button id="sprinkle">✦ 골고루 뿌려 주기</button></div><p class="smallprint"><button class="text-button" id="undo">↶ 마지막 토핑 취소</button><button class="text-button" id="clear-toppings">토핑 모두 지우기</button></p>`;box.querySelectorAll('[data-topping]').forEach(b=>b.onclick=()=>{state.topping=b.dataset.topping;render()});$('#sprinkle').onclick=()=>{selectedFoods().forEach((f,i)=>{for(let j=0;j<4;j++)addDot(i,40+Math.random()*140,80+j*65)});draw()};$('#undo').onclick=()=>{state.dots.pop();draw()};$('#clear-toppings').onclick=()=>{state.dots=[];draw()};
 }else{box.innerHTML=`<label class="field" for="to">받는 사람</label><input id="to" placeholder="예: 세상에서 제일 소중한 너" maxlength="20" value="${esc(state.to)}"><label class="field" for="message">함께 보낼 마음 <span style="color:var(--muted)">(최대 60자)</span></label><textarea id="message" rows="2" maxlength="60">${esc(state.message)}</textarea><label class="field" for="from">보내는 사람</label><input id="from" placeholder="예: 빼빼로 장인" maxlength="20" value="${esc(state.from)}"><label class="field">포장지 색상</label><div class="color-options">${[['#f5dfd7','복숭아'],['#e1e7d5','세이지'],['#e5dfed','라벤더'],['#f1e4bf','버터']].map(([color,name])=>`<button style="background:${color}" class="${state.paper===color?'selected':''}" data-paper="${color}" aria-label="${name} 포장지" aria-pressed="${state.paper===color}"></button>`).join('')}</div><div class="finish-buttons"><button class="primary" id="copy-image">▣ 완성 이미지 복사</button><button class="secondary" id="view-image">↗ 이미지 크게 보기</button></div><p class="smallprint">복사한 이미지는 카카오톡·메신저·문서에 붙여넣어 보내세요. 복사가 지원되지 않으면 크게 보기에서 이미지를 길게 누르거나 오른쪽 클릭해 복사하세요.</p>`;['to','from','message'].forEach(k=>$('#'+k).oninput=e=>{state[k]=e.target.value;draw()});box.querySelectorAll('[data-paper]').forEach(b=>b.onclick=()=>{state.paper=b.dataset.paper;box.querySelectorAll('[data-paper]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});draw()});$('#copy-image').onclick=copyImage;$('#view-image').onclick=showImage;
 }if(state.step===0&&$('.ingredients'))$('.ingredients').scrollTop=ingredientScroll;draw();
}
function animate(key,max,duration){if(busy)return;busy=true;render();const start=performance.now();timer=setInterval(()=>{const p=Math.min((performance.now()-start)/duration,1);state[key]=p*max;draw();const track=$('.progress-track');if(track){track.setAttribute('aria-valuenow',Math.round(p*100));$('.progress-fill').style.width=(p*100)+'%'}if(p===1){clearInterval(timer);timer=null;busy=false;render();toast(key==='melt'?'초콜릿이 부드럽게 녹았어요!':'달콤하게 코팅 완료!')}},30)}
function addDot(food,x,y){if(state.dots.length>=200){state.dots.shift()}state.dots.push({food,x,y,type:state.topping,seed:Math.floor(Math.random()*100000)})}
canvas.addEventListener('pointerdown',e=>{if(state.step!==3)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*880,y=(e.clientY-r.top)/r.height*880;const fs=selectedFoods();for(let i=fs.length-1;i>=0;i--){const p=foodLayout(880,880,fs.length,i),dx=x-p.x,dy=y-p.y;const fx=((dx*Math.cos(p.rotation)+dy*Math.sin(p.rotation))/p.size+.5)*440,fy=((-dx*Math.sin(p.rotation)+dy*Math.cos(p.rotation))/p.size+.5)*440;if(fx<0||fx>=440||fy<0||fy>=440)continue;const image=foodImage(fs[i],1,[]);if(!coatingAt(fs[i],fx,fy,state.coat))continue;addDot(i,fx/2,fy);draw();return}toast('재료의 초콜릿 부분을 눌러 주세요.');});
async function imageBlob(){await document.fonts.ready;await foodAtlasReady;const c=document.createElement('canvas');c.width=1500;c.height=1500;drawGift(c.getContext('2d'),1500,1500);return new Promise(resolve=>c.toBlob(resolve,'image/png'))}
let imagePreviewUrl=null;
async function showImage(){try{const blob=await imageBlob();if(!blob)throw Error();if(imagePreviewUrl)URL.revokeObjectURL(imagePreviewUrl);imagePreviewUrl=URL.createObjectURL(blob);$('#full-image').src=imagePreviewUrl;if(!$('#image-dialog').open)$('#image-dialog').showModal()}catch{toast('이미지를 만들지 못했어요. 다시 시도해 주세요.')}}
async function copyImage(){const button=$('#copy-image');try{if(!navigator.clipboard?.write||typeof ClipboardItem==='undefined')throw Error('unsupported');const pending=imageBlob().then(blob=>{if(!blob)throw Error('image');return blob});await navigator.clipboard.write([new ClipboardItem({'image/png':pending})]);toast('이미지를 복사했어요! 메신저에 붙여넣어 주세요.');if(button?.isConnected){button.textContent='✓ 이미지 복사 완료';setTimeout(()=>{if(button.isConnected)button.textContent='▣ 완성 이미지 복사'},2500)}}catch{await showImage();toast('자동 복사가 지원되지 않아요. 이미지에서 오른쪽 클릭하거나 길게 눌러 복사해 주세요.')}}
$('#image-close').onclick=()=>$('#image-dialog').close();
$('#next').onclick=()=>{if($('#next').disabled||busy||state.step>=4)return;state.step++;render()};$('#back').onclick=()=>{if(busy)return;if(state.step>0)state.step--;render()};$('#reset').onclick=()=>{if(!confirm('지금 만든 빼빼로를 지우고 새로 시작할까요?'))return;clearInterval(timer);busy=false;Object.assign(state,{step:0,selected:['stick'],choc:'milk',melt:0,coat:0,dots:[],filter:'all',to:'',from:'',message:'조금 이상해도, 내 마음은 진심이야!'});render()};$('#how').onclick=()=>$('#guide').showModal();$('.close').onclick=()=>$('#guide').close();$('#guide').addEventListener('click',e=>{if(e.target===$('#guide')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
drawHero();render();Promise.all([document.fonts.ready,foodAtlasReady]).then(()=>{drawHero();draw()});
